747	func (v *ViewChanger) processViewDataMsg() {
748		if len(v.viewDataMsgs.voted) < v.quorum {
749			return // need enough (quorum) data to continue
750		}
751		v.Logger.Debugf("Node %d got a quorum of viewData messages", v.SelfID)
752		ok, _, _, err := CheckInFlight(v.getViewDataMessages(), v.f, v.quorum, v.N, v.Verifier)
753		if err != nil {
754			v.Logger.Panicf("Node %d checked the in flight and it got an error: %v", v.SelfID, err)
755		}
756		if !ok {
757			v.Logger.Debugf("Node %d checked the in flight and it was invalid", v.SelfID)
758			return
759		}
760		v.Logger.Debugf("Node %d checked the in flight and it was valid", v.SelfID)
761		// create the new view message
762		signedMsgs := make([]*protos.SignedViewData, 0)
763		myMsg := v.prepareViewDataMsg()                      // since it might have changed by now
764		signedMsgs = append(signedMsgs, myMsg.GetViewData()) // leader's message will always be the first
765		close(v.viewDataMsgs.votes)
766		for vt := range v.viewDataMsgs.votes {
767			if vt.sender == v.SelfID {
768				continue // ignore my old message
769			}
770			signedMsgs = append(signedMsgs, vt.GetViewData())
771		}
772		msg := &protos.Message{
773			Content: &protos.Message_NewView{
774				NewView: &protos.NewView{
775					SignedViewData: signedMsgs,
776				},
777			},
778		}
779		v.Logger.Debugf("Node %d is broadcasting a new view msg", v.SelfID)
780		v.Comm.BroadcastConsensus(msg)
781		v.Logger.Debugf("Node %d sent a new view msg to self", v.SelfID)
782		v.processMsg(v.SelfID, msg) // also send to myself // TODO consider not reprocessing this message
783		v.viewDataMsgs.clear(v.N)
784		v.Logger.Debugf("Node %d sent a new view msg", v.SelfID)
785	}
786	
787	// returns view data messages included in votes
788	func (v *ViewChanger) getViewDataMessages() []*protos.ViewData {
789		var messages []*protos.ViewData
790		for range len(v.viewDataMsgs.votes) {
791			vt := <-v.viewDataMsgs.votes
792			vd := &protos.ViewData{}
793			if err := proto.Unmarshal(vt.GetViewData().RawViewData, vd); err != nil {
794				v.Logger.Panicf("Node %d was unable to unmarshal viewData message, error: %v", v.SelfID, err)
795			}
796			messages = append(messages, vd)
797			v.viewDataMsgs.votes <- vt
798		}
799		return messages
800	}
