802	type possibleProposal struct {
803		proposal    *protos.Proposal
804		preprepared int
805		noArgument  int
806	}
807	
808	type proposalAndMetadata struct {
809		proposal *protos.Proposal
810		metadata *protos.ViewMetadata
811	}
812	
813	// CheckInFlight checks if there is an in-flight proposal that needs to be decided on (because a node might decided on it already)
814	func CheckInFlight(messages []*protos.ViewData, f int, quorum int, n uint64, verifier api.Verifier) (ok, noInFlight bool, inFlightProposal *protos.Proposal, err error) {
815		expectedSequence := maxLastDecisionSequence(messages) + 1
816		possibleProposals := make([]*possibleProposal, 0)
817		proposalsAndMetadata := make([]*proposalAndMetadata, 0)
818		noInFlightCount := 0
819		for _, vd := range messages {
820			if vd.InFlightProposal == nil { // there is no in flight proposal here
821				noInFlightCount++
822				proposalsAndMetadata = append(proposalsAndMetadata, &proposalAndMetadata{nil, nil})
823				continue
824			}
825	
826			if vd.InFlightProposal.Metadata == nil { // should have been validated earlier
827				return false, false, nil, errors.New("node has a view data message where the in flight proposal metadata is nil")
828			}
829	
830			inFlightMetadata := &protos.ViewMetadata{}
831			if err = proto.Unmarshal(vd.InFlightProposal.Metadata, inFlightMetadata); err != nil { // should have been validated earlier
832				return false, false, nil, fmt.Errorf("node was unable to unmarshal the in flight proposal metadata, error: %w", err)
833			}
834	
835			proposalsAndMetadata = append(proposalsAndMetadata, &proposalAndMetadata{vd.InFlightProposal, inFlightMetadata})
836	
837			if inFlightMetadata.LatestSequence != expectedSequence { // the in flight proposal sequence is not as expected
838				noInFlightCount++
839				continue
840			}
841	
842			// now the in flight proposal is with the expected sequence
843			// find possible proposals
844	
845			if !vd.InFlightPrepared { // no prepared so isn't a possible proposal
846				noInFlightCount++
847				continue
848			}
849	
850			// this proposal is prepared and so it is possible
851			alreadyExists := false
852			for _, p := range possibleProposals {
853				if proto.Equal(p.proposal, vd.InFlightProposal) {
854					alreadyExists = true
855					break
856				}
857			}
858			if !alreadyExists {
859				// this is not a proposal we have seen before
860				possibleProposals = append(possibleProposals, &possibleProposal{proposal: vd.InFlightProposal})
861			}
862		}
863	
864		// fill out info on all possible proposals
865		for _, prop := range proposalsAndMetadata {
866			for _, possible := range possibleProposals {
867				if prop.proposal == nil {
868					possible.noArgument++
869					continue
870				}
871	
872				if prop.metadata.LatestSequence != expectedSequence {
873					possible.noArgument++
874					continue
875				}
876	
877				if proto.Equal(prop.proposal, possible.proposal) {
878					possible.noArgument++
879					possible.preprepared++
880				}
881			}
882		}
883	
884		// see if there is an in flight proposal that is agreed on
885		agreed := -1
886		for i, possible := range possibleProposals {
887			if possible.preprepared < f+1 { // condition A2 doesn't hold
888				continue
889			}
890			if possible.noArgument < quorum { // condition A1 doesn't hold
891				continue
892			}
893			agreed = i
894			break
895		}
896	
897		// condition A holds
898		if agreed != -1 {
899			return true, false, possibleProposals[agreed].proposal, nil
900		}
901	
902		// condition B holds
903		if noInFlightCount >= quorum { // there is a quorum of messages that support that there is no prepared in flight proposal
904			return true, true, nil, nil
905		}
906	
907		return false, false, nil, nil
908	}
909	
910	// returns the highest sequence of a last decision within the given view data messages
911	func maxLastDecisionSequence(messages []*protos.ViewData) uint64 {
912		max := uint64(0)
913		for _, vd := range messages {
914			if vd.LastDecision == nil {
915				panic("The last decision is not set")
916			}
917			if vd.LastDecision.Metadata == nil { // this is a genesis proposal
918				continue
919			}
920			md := &protos.ViewMetadata{}
921			if err := proto.Unmarshal(vd.LastDecision.Metadata, md); err != nil {
922				panic(fmt.Sprintf("Unable to unmarshal the last decision metadata, err: %v", err))
923			}
924			if md.LatestSequence > max {
925				max = md.LatestSequence
926			}
927		}
928		return max
929	}
