931	func (v *ViewChanger) validateNewViewMsg(msg *protos.NewView) (valid bool, sync bool, deliver bool) {
932		signed := msg.GetSignedViewData()
933		nodesMap := make(map[uint64]struct{}, v.N)
934		validViewDataMsgs := 0
935		mySequence, myLastDecision := v.extractCurrentSequence()
936		for _, svd := range signed {
937			if _, exist := nodesMap[svd.Signer]; exist {
938				continue // seen data from this node already
939			}
940			nodesMap[svd.Signer] = struct{}{}
941	
942			vd := &protos.ViewData{}
943			if err := proto.Unmarshal(svd.RawViewData, vd); err != nil {
944				v.Logger.Errorf("Node %d was unable to unmarshal viewData from the newView message, error: %v", v.SelfID, err)
945				return false, false, false
946			}
947	
948			if vd.NextView != v.currView {
949				v.Logger.Warnf("Node %d is processing newView message, but nextView of %s is %d, while the currView is %d", v.SelfID, signedViewDataToString(svd), vd.NextView, v.currView)
950				return false, false, false
951			}
952	
953			if vd.LastDecision == nil {
954				v.Logger.Warnf("Node %d is processing newView message, but the last decision of %s is not set", v.SelfID, signedViewDataToString(svd))
955				return false, false, false
956			}
957	
958			// Begin to check the last decision within the view data message.
959			//
960			// This node might be ahead, in which case it might not have the right config to validate
961			// the decision and signatures, and so the view data message is deemed invalid.
962			//
963			// If this node is too far behind then it needs to sync.
964			// No validation can be done since it might not have the appropriate config.
965			//
966			// If the last decision sequence is equal to this node's sequence then we check that the decisions are equal.
967			// However, we cannot validate the decision signatures since this last decision might have been a reconfig.
968			//
969			// Lastly, this node is behind by one sequence, and so it validates the decision and delivers it.
970			// Only after delivery the message signature is verified, again since this decision might have been a reconfig.
971	
972			if vd.LastDecision.Metadata == nil { // this is a genesis proposal
973				if mySequence > 0 {
974					// can't validate the signature since I am ahead
975					if err := ValidateInFlight(vd.InFlightProposal, 0); err != nil {
976						v.Logger.Warnf("Node %d is processing newView message, but the in flight proposal of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
977						return false, false, false
978					}
979					validViewDataMsgs++
980					continue
981				}
982				if err := v.Verifier.VerifySignature(types.Signature{ID: svd.Signer, Value: svd.Signature, Msg: svd.RawViewData}); err != nil {
983					v.Logger.Warnf("Node %d is processing newView message, but signature of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
984					return false, false, false
985				}
986				if err := ValidateInFlight(vd.InFlightProposal, 0); err != nil {
987					v.Logger.Warnf("Node %d is processing newView message, but the in flight proposal of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
988					return false, false, false
989				}
990				validViewDataMsgs++
991				continue
992			}
993	
994			lastDecisionMD := &protos.ViewMetadata{}
995			if err := proto.Unmarshal(vd.LastDecision.Metadata, lastDecisionMD); err != nil {
996				v.Logger.Warnf("Node %d is processing newView message, but was unable to unmarshal the last decision of %s, err: %v", v.SelfID, signedViewDataToString(svd), err)
997				return false, false, false
998			}
999			if lastDecisionMD.ViewId >= vd.NextView {
1000				v.Logger.Warnf("Node %d is processing newView message, but the last decision view %d is greater or equal to requested next view %d of %s", v.SelfID, lastDecisionMD.ViewId, vd.NextView, signedViewDataToString(svd))
1001				return false, false, false
1002			}
1003	
1004			if lastDecisionMD.LatestSequence > mySequence+1 { // this is a decision in the future, can't verify it and should sync
1005				v.Synchronizer.Sync() // TODO check if I managed to sync to latest decision, revalidate new view, and join the other nodes
1006				return true, true, false
1007			}
1008	
1009			if lastDecisionMD.LatestSequence < mySequence { // this is a decision in the past
1010				// can't validate the signature since I am ahead
1011				if err := ValidateInFlight(vd.InFlightProposal, lastDecisionMD.LatestSequence); err != nil {
1012					v.Logger.Warnf("Node %d is processing newView message, but the in flight proposal of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
1013					return false, false, false
1014				}
1015				validViewDataMsgs++
1016				continue
1017			}
1018	
1019			if lastDecisionMD.LatestSequence == mySequence { // just make sure that we have the same last decision, can't verify the signatures of this last decision since this might have been a reconfiguration
1020				// the signature on this message can be verified
1021				if err := v.Verifier.VerifySignature(types.Signature{ID: svd.Signer, Value: svd.Signature, Msg: svd.RawViewData}); err != nil {
1022					v.Logger.Warnf("Node %d is processing newView message, but signature of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
1023					return false, false, false
1024				}
1025	
1026				// compare the last decision itself
1027				if !proto.Equal(vd.LastDecision, myLastDecision) {
1028					v.Logger.Warnf("Node %d is processing newView message, but the last decision of %s is with the same sequence but is not equal", v.SelfID, signedViewDataToString(svd))
1029					return false, false, false
1030				}
1031	
1032				if err := ValidateInFlight(vd.InFlightProposal, lastDecisionMD.LatestSequence); err != nil {
1033					v.Logger.Warnf("Node %d is processing newView message, but the in flight proposal of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
1034					return false, false, false
1035				}
1036	
1037				validViewDataMsgs++
1038				continue
1039			}
1040	
1041			if lastDecisionMD.LatestSequence != mySequence+1 {
1042				v.Logger.Warnf("Node %d is processing newView message, but the last decision sequence is not equal to this node's sequence + 1", v.SelfID)
1043				return false, false, false
1044			}
1045	
1046			_, err := ValidateLastDecision(vd, v.quorum, v.N, v.Verifier)
1047			if err != nil {
1048				v.Logger.Warnf("Node %d is processing newView message, but the last decision of %s is invalid, reason: %v", v.SelfID, signedViewDataToString(svd), err)
1049				return false, false, false
1050			}
1051	
1052			proposal := types.Proposal{
1053				Header:               vd.LastDecision.Header,
1054				Metadata:             vd.LastDecision.Metadata,
1055				Payload:              vd.LastDecision.Payload,
1056				VerificationSequence: int64(vd.LastDecision.VerificationSequence),
1057			}
1058			signatures := make([]types.Signature, 0)
1059			for _, sig := range vd.LastDecisionSignatures {
1060				signature := types.Signature{
1061					ID:    sig.Signer,
1062					Value: sig.Value,
1063					Msg:   sig.Msg,
1064				}
1065				signatures = append(signatures, signature)
1066			}
1067			v.deliverDecision(proposal, signatures)
1068	
1069			select { // if there was a delivery with a reconfig we need to stop here before verify signature
1070			case <-v.stopChan:
1071				return false, false, false
1072			default:
1073			}
1074	
1075			if err = v.Verifier.VerifySignature(types.Signature{ID: svd.Signer, Value: svd.Signature, Msg: svd.RawViewData}); err != nil {
1076				v.Logger.Warnf("Node %d is processing newView message, but signature of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
1077				return false, false, false
1078			}
1079	
1080			if err = ValidateInFlight(vd.InFlightProposal, lastDecisionMD.LatestSequence); err != nil {
1081				v.Logger.Warnf("Node %d is processing newView message, but the in flight proposal of %s is invalid, error: %v", v.SelfID, signedViewDataToString(svd), err)
1082				return false, false, false
1083			}
1084	
1085			return true, false, true
1086		}
1087	
1088		if validViewDataMsgs < v.quorum {
1089			v.Logger.Warnf("Node %d is processing newView message, but there was only %d valid view data messages while the quorum is %d", v.SelfID, validViewDataMsgs, v.quorum)
1090			return false, false, false
1091		}
1092	
1093		v.Logger.Debugf("Node %d found a quorum of valid view data messages within the new view message", v.SelfID)
1094		return true, false, false
1095	}
1096	
1097	func (v *ViewChanger) extractViewDataMessages(msg *protos.NewView) []*protos.ViewData {
1098		signed := msg.GetSignedViewData()
1099		vds := make([]*protos.ViewData, 0)
1100		for _, svd := range signed {
1101			vd := &protos.ViewData{}
1102			if err := proto.Unmarshal(svd.RawViewData, vd); err != nil {
1103				v.Logger.Panicf("Node %d was unable to unmarshal viewData from the newView message, error: %v", v.SelfID, err)
1104			}
1105			vds = append(vds, vd)
1106		}
1107		return vds
1108	}
1109	
1110	func (v *ViewChanger) processNewViewMsg(msg *protos.NewView) {
1111		valid, calledSync, calledDeliver := v.validateNewViewMsg(msg)
1112		for calledDeliver {
1113			v.Logger.Debugf("Node %d is processing a newView message, and delivered a proposal", v.SelfID)
1114			valid, calledSync, calledDeliver = v.validateNewViewMsg(msg)
1115		}
1116		if !valid {
1117			v.Logger.Warnf("Node %d is processing a newView message, but the message is invalid", v.SelfID)
1118			return
1119		}
1120		if calledSync {
1121			v.Logger.Debugf("Node %d is processing a newView message, and requested a sync", v.SelfID)
1122			return
1123		}
1124	
1125		ok, noInFlight, inFlightProposal, err := CheckInFlight(v.extractViewDataMessages(msg), v.f, v.quorum, v.N, v.Verifier)
1126		if err != nil {
1127			v.Logger.Panicf("The check of the in flight proposal by node %d returned an error: %v", v.SelfID, err)
1128		}
1129		if !ok {
1130			v.Logger.Debugf("The check of the in flight proposal by node %d did not pass", v.SelfID)
1131			return
1132		}
1133	
1134		if !noInFlight && !v.commitInFlightProposal(inFlightProposal) {
1135			v.Logger.Warnf("Node %d was unable to commit the in flight proposal, not changing the view", v.SelfID)
1136			return
1137		}
1138	
1139		mySequence, _ := v.extractCurrentSequence()
1140	
1141		newViewToSave := &protos.SavedMessage{
1142			Content: &protos.SavedMessage_NewView{
1143				NewView: &protos.ViewMetadata{
1144					ViewId:         v.currView,
1145					LatestSequence: mySequence,
1146				},
1147			},
1148		}
1149		if err = v.State.Save(newViewToSave); err != nil {
1150			v.Logger.Panicf("Failed to save message to state, error: %v", err)
1151		}
1152	
1153		select { // if there was a delivery or sync with a reconfig when committing the in-flight proposal we should stop
1154		case <-v.stopChan:
1155			return
1156		default:
1157		}
1158	
1159		v.realView = v.currView
1160		v.MetricsViewChange.RealView.Set(float64(v.realView))
1161		v.nvs.clear()
1162		v.Controller.ViewChanged(v.currView, mySequence+1)
1163	
1164		v.RequestsTimer.RestartTimers()
1165		v.checkTimeout = false
1166		v.backOffFactor = 1 // reset
1167	}
1168	
1169	func (v *ViewChanger) deliverDecision(proposal types.Proposal, signatures []types.Signature) {
1170		v.Logger.Debugf("Delivering to app from deliverDecision the last decision proposal")
1171		reconfig := v.Application.Deliver(proposal, signatures)
1172		if reconfig.InLatestDecision {
1173			v.close()
1174		}
1175		v.Logger.Debugf("Delivering end to app from deliverDecision the last decision proposal")
1176	
1177		requests := v.Verifier.RequestsFromProposal(proposal)
1178		for _, reqInfo := range requests {
1179			if err := v.RequestsTimer.RemoveRequest(reqInfo); err != nil {
1180				v.Logger.Warnf("Error during remove of request %s from the pool, err: %v", reqInfo, err)
1181			}
1182		}
1183		v.Pruner.MaybePruneRevokedRequests()
1184	}
1185	
1186	func (v *ViewChanger) commitInFlightProposal(proposal *protos.Proposal) (success bool) {
1187		myLastDecision, _ := v.Checkpoint.Get()
1188		if proposal == nil {
1189			v.Logger.Panicf("The in flight proposal is nil")
1190			return
1191		}
1192		proposalMD := &protos.ViewMetadata{}
1193		if err := proto.Unmarshal(proposal.Metadata, proposalMD); err != nil {
1194			v.Logger.Panicf("Node %d is unable to unmarshal the in flight proposal metadata, err: %v", v.SelfID, err)
1195		}
1196	
1197		if myLastDecision.Metadata != nil { // if metadata is nil then I am at genesis proposal and I should commit the in flight proposal anyway
1198			lastDecisionMD := &protos.ViewMetadata{}
1199			if err := proto.Unmarshal(myLastDecision.Metadata, lastDecisionMD); err != nil {
1200				v.Logger.Panicf("Node %d is unable to unmarshal its own last decision metadata from checkpoint, err: %v", v.SelfID, err)
1201			}
1202			if lastDecisionMD.LatestSequence == proposalMD.LatestSequence {
1203				v.Logger.Debugf("Node %d already decided on sequence %d and so it will not commit the in flight proposal with the same sequence", v.SelfID, lastDecisionMD.LatestSequence)
1204				v.Logger.Debugf("Node %d is comparing its last decision with the in flight proposal with the same sequence %d", v.SelfID, lastDecisionMD.LatestSequence)
1205				if !proto.Equal(myLastDecision, proposal) {
1206					v.Logger.Warnf("Node %d compared its last decision with the in flight proposal, which has the same sequence, but they are not equal", v.SelfID)
1207					return false
1208				}
1209				return true // I already decided on the in flight proposal
1210			}
1211			if lastDecisionMD.LatestSequence != proposalMD.LatestSequence-1 {
1212				v.Logger.Panicf("Node %d got an in flight proposal with sequence %d while its last decision was on sequence %d", v.SelfID, proposalMD.LatestSequence, lastDecisionMD.LatestSequence)
1213			}
1214		}
1215	
1216		v.Logger.Debugf("Node %d is creating a view %d for the in flight proposal", v.SelfID, proposalMD.ViewId)
1217	
1218		inFlightViewNum := proposalMD.ViewId
1219		inFlightViewLatestSeq := proposalMD.LatestSequence
1220	
1221		v.inFlightViewLock.Lock()
1222		inFlightView := &View{
1223			RetrieveCheckpoint: v.Checkpoint.Get,
1224			DecisionsPerLeader: v.DecisionsPerLeader,
1225			SelfID:             v.SelfID,
1226			N:                  v.N,
1227			NodesList:          v.NodesList,
1228			Number:             inFlightViewNum,
1229			LeaderID:           v.SelfID, // so that no byzantine leader will cause a complain
1230			Quorum:             v.quorum,
1231			Decider:            v,
1232			FailureDetector:    v,
1233			Sync:               v,
1234			Logger:             v.Logger,
1235			Comm:               v.Comm,
1236			Verifier:           v.Verifier,
1237			Signer:             v.Signer,
1238			ProposalSequence:   inFlightViewLatestSeq,
1239			State:              v.State,
1240			InMsgQSize:         v.InMsqQSize,
1241			ViewSequences:      v.ViewSequences,
1242			Phase:              PREPARED,
1243			MetricsBlacklist:   v.MetricsBlacklist,
1244			MetricsView:        v.MetricsView,
1245		}
1246		inFlightView.MetricsView.ViewNumber.Set(float64(inFlightView.Number))
1247		inFlightView.MetricsView.LeaderID.Set(float64(inFlightView.LeaderID))
1248		inFlightView.MetricsView.ProposalSequence.Set(float64(inFlightView.ProposalSequence))
1249		inFlightView.MetricsView.DecisionsInView.Set(float64(inFlightView.DecisionsInView))
1250		inFlightView.MetricsView.Phase.Set(float64(inFlightView.Phase))
1251	
1252		v.inFlightView = inFlightView
1253		v.inFlightView.inFlightProposal = &types.Proposal{
1254			VerificationSequence: int64(proposal.VerificationSequence),
1255			Metadata:             proposal.Metadata,
1256			Payload:              proposal.Payload,
1257			Header:               proposal.Header,
1258		}
1259		v.inFlightView.myProposalSig = v.Signer.SignProposal(*v.inFlightView.inFlightProposal, nil)
1260		v.inFlightView.lastBroadcastSent = &protos.Message{
1261			Content: &protos.Message_Commit{
1262				Commit: &protos.Commit{
1263					View:   v.inFlightView.Number,
1264					Digest: v.inFlightView.inFlightProposal.Digest(),
1265					Seq:    v.inFlightView.ProposalSequence,
1266					Signature: &protos.Signature{
1267						Signer: v.inFlightView.myProposalSig.ID,
1268						Value:  v.inFlightView.myProposalSig.Value,
1269						Msg:    v.inFlightView.myProposalSig.Msg,
1270					},
1271				},
1272			},
1273		}
1274	
1275		v.Logger.Debugf("Waiting two ticks before starting in-flight view")
1276		<-v.Ticker
1277		<-v.Ticker
1278	
1279		inFlightView.Start()
1280		defer inFlightView.Abort()
1281	
1282		v.inFlightViewLock.Unlock()
1283	
1284		v.Logger.Debugf("Node %d started a view %d for the in flight proposal", v.SelfID, v.inFlightView.Number)
1285	
1286		// wait for view to finish or time out
1287		for {
1288			select {
1289			case <-v.inFlightDecideChan:
1290				v.Logger.Infof("In-flight view %d with latest sequence %d has committed a decision", inFlightViewNum, inFlightViewLatestSeq)
1291				return true
1292			case <-v.inFlightSyncChan:
1293				v.Logger.Infof("In-flight view %d with latest sequence %d has asked to sync", inFlightViewNum, inFlightViewLatestSeq)
1294				return false
1295			case now := <-v.Ticker:
1296				v.lastTick = now
1297				if v.checkIfTimeout(now) {
1298					v.Logger.Infof("Timeout expired waiting on In-flight %d with latest sequence view to commit %d", inFlightViewNum, inFlightViewLatestSeq)
1299					return false
1300				}
1301			case <-v.stopChan:
1302				v.Logger.Infof("View changer was instructed to stop")
1303				return false
1304			}
1305		}
1306	}
1307	
1308	// Decide delivers to the application and informs the view changer after delivery
1309	func (v *ViewChanger) Decide(proposal types.Proposal, signatures []types.Signature, requests []types.RequestInfo) {
1310		v.inFlightView.stop()
1311		v.Logger.Debugf("Delivering to app from Decide the last decision proposal")
1312		reconfig := v.Application.Deliver(proposal, signatures)
1313		if reconfig.InLatestDecision {
1314			v.close()
1315		}
1316		v.Logger.Debugf("Delivering end to app from Decide the last decision proposal")
1317	
1318		for _, reqInfo := range requests {
1319			if err := v.RequestsTimer.RemoveRequest(reqInfo); err != nil {
1320				v.Logger.Warnf("Error during remove of request %s from the pool, err: %v", reqInfo, err)
1321			}
1322		}
1323		v.Pruner.MaybePruneRevokedRequests()
1324	
1325		select {
1326		case v.inFlightDecideChan <- struct{}{}:
1327			return
1328		case <-v.stopChan:
1329			return
1330		}
1331	}
1332	
1333	// Complain panics when a view change is requested
1334	func (v *ViewChanger) Complain(viewNum uint64, stopView bool) {
1335		v.Logger.Panicf("Node %d has complained while in the view for the in flight proposal", v.SelfID)
1336	}
1337	
1338	// Sync calls the synchronizer and informs the view changer of the sync
1339	func (v *ViewChanger) Sync() {
1340		// the in flight proposal view asked to sync
1341		v.Logger.Debugf("Node %d is calling sync because the in flight proposal view has asked to sync", v.SelfID)
1342		v.Synchronizer.Sync()
1343		v.inFlightSyncChan <- struct{}{}
1344	}
1345	
1346	// HandleViewMessage passes a message to the in flight proposal view if applicable
1347	func (v *ViewChanger) HandleViewMessage(sender uint64, m *protos.Message) {
1348		v.inFlightViewLock.RLock()
1349		defer v.inFlightViewLock.RUnlock()
1350		if view := v.inFlightView; view != nil {
1351			v.Logger.Debugf("Node %d is passing a message to the in flight view", v.SelfID)
1352			view.HandleMessage(sender, m)
1353		}
1354	}
1355	
1356	func (v *ViewChanger) blacklist() []uint64 {
1357		prop, _ := v.Checkpoint.Get()
1358		md := &protos.ViewMetadata{}
1359		if err := proto.Unmarshal(prop.Metadata, md); err != nil {
1360			v.Logger.Panicf("Failed unmarshalling metadata: %v", err)
1361		}
1362		return md.BlackList
1363	}
1364

