6	package bft
7	
8	import (
9		"errors"
10		"fmt"
11	
12		"github.com/hyperledger-labs/SmartBFT/pkg/api"
13		"github.com/hyperledger-labs/SmartBFT/pkg/types"
14		protos "github.com/hyperledger-labs/SmartBFT/smartbftprotos"
15		"google.golang.org/protobuf/proto"
16	)
17	
18	type StateRecorder struct {
19		SavedMessages []*protos.SavedMessage
20	}
21	
22	func (sr *StateRecorder) Save(message *protos.SavedMessage) error {
23		sr.SavedMessages = append(sr.SavedMessages, message)
24		return nil
25	}
26	
27	func (*StateRecorder) Restore(_ *View) error {
28		panic("should not be used")
29	}
30	
31	type PersistedState struct {
32		InFlightProposal *InFlightData
33		Entries          [][]byte
34		Logger           api.Logger
35		WAL              api.WriteAheadLog
36	}
37	
38	func (ps *PersistedState) Save(msgToSave *protos.SavedMessage) error {
39		if proposed := msgToSave.GetProposedRecord(); proposed != nil {
40			ps.storeProposal(proposed)
41		}
42		if prepared := msgToSave.GetCommit(); prepared != nil {
43			ps.storePrepared(prepared)
44		}
45	
46		b, err := proto.Marshal(msgToSave)
47		if err != nil {
48			ps.Logger.Panicf("Failed marshaling message: %v", err)
49		}
50		// It is only safe to truncate if we either:
51		//
52		// 1) Process a pre-prepare, because it means we safely persisted the
53		// previous proposal and have a stable checkpoint.
54		// 2) Acquired a new view message which contains 2f+1 attestations
55		//    of the cluster agreeing to a new view configuration.
56		newProposal := msgToSave.GetProposedRecord() != nil
57		// TODO: handle view message here as well, and add "|| finalizedView" to truncate flag
58		return ps.WAL.Append(b, newProposal)
59	}
60	
61	func (ps *PersistedState) storeProposal(proposed *protos.ProposedRecord) {
62		proposal := proposed.PrePrepare.Proposal
63		proposalToStore := types.Proposal{
64			VerificationSequence: int64(proposal.VerificationSequence),
65			Header:               proposal.Header,
66			Payload:              proposal.Payload,
67			Metadata:             proposal.Metadata,
68		}
69		ps.InFlightProposal.StoreProposal(proposalToStore)
70	}
71	
72	func (ps *PersistedState) storePrepared(commitMsg *protos.Message) {
73		cmt := commitMsg.GetCommit()
74		ps.InFlightProposal.StorePrepares(cmt.View, cmt.Seq)
75	}
76	
77	func (ps *PersistedState) LoadNewViewIfApplicable() (*types.ViewAndSeq, error) {
78		entries := ps.Entries
79		if len(entries) == 0 {
80			ps.Logger.Infof("Nothing to restore")
81			return nil, nil
82		}
83		lastEntry := entries[len(entries)-1]
84		lastPersistedMessage := &protos.SavedMessage{}
85		if err := proto.Unmarshal(lastEntry, lastPersistedMessage); err != nil {
86			ps.Logger.Errorf("Failed unmarshaling last entry from WAL: %v", err)
87			return nil, fmt.Errorf("failed unmarshaling last entry from WAL: %w", err)
88		}
89		if newViewMsg := lastPersistedMessage.GetNewView(); newViewMsg != nil {
90			ps.Logger.Infof("last entry in WAL is a newView record")
91			return &types.ViewAndSeq{View: newViewMsg.ViewId, Seq: newViewMsg.LatestSequence}, nil
92		}
93		return nil, nil
94	}
95	
96	func (ps *PersistedState) LoadViewChangeIfApplicable() (*protos.ViewChange, error) {
97		entries := ps.Entries
98		if len(entries) == 0 {
99			ps.Logger.Infof("Nothing to restore")
100			return nil, nil
101		}
102		lastEntry := entries[len(entries)-1]
103		lastPersistedMessage := &protos.SavedMessage{}
104		if err := proto.Unmarshal(lastEntry, lastPersistedMessage); err != nil {
105			ps.Logger.Errorf("Failed unmarshaling last entry from WAL: %v", err)
106			return nil, fmt.Errorf("failed unmarshaling last entry from WAL: %w", err)
107		}
108		if viewChangeMsg := lastPersistedMessage.GetViewChange(); viewChangeMsg != nil {
109			ps.Logger.Infof("last entry in WAL is a viewChange message")
110			return viewChangeMsg, nil
111		}
112		return nil, nil
113	}
114	
115	func (ps *PersistedState) Restore(v *View) error {
116		// Unless we conclude otherwise, we're in a COMMITTED state
117		v.Phase = COMMITTED
118	
119		entries := ps.Entries
120		if len(entries) == 0 {
121			ps.Logger.Infof("Nothing to restore")
122			return nil
123		}
124	
125		ps.Logger.Infof("WAL contains %d entries", len(entries))
126	
127		lastEntry := entries[len(entries)-1]
128		lastPersistedMessage := &protos.SavedMessage{}
129		if err := proto.Unmarshal(lastEntry, lastPersistedMessage); err != nil {
130			ps.Logger.Errorf("Failed unmarshaling last entry from WAL: %v", err)
131			return fmt.Errorf("failed unmarshaling last entry from WAL: %w", err)
132		}
133	
134		if proposed := lastPersistedMessage.GetProposedRecord(); proposed != nil {
135			return ps.recoverProposed(proposed, v)
136		}
137	
138		if commitMsg := lastPersistedMessage.GetCommit(); commitMsg != nil {
139			return ps.recoverPrepared(commitMsg, v, entries)
140		}
141	
142		if newViewMsg := lastPersistedMessage.GetNewView(); newViewMsg != nil {
143			ps.Logger.Infof("last entry in WAL is a newView record")
144			return nil
145		}
146	
147		if viewChangeMsg := lastPersistedMessage.GetViewChange(); viewChangeMsg != nil {
148			ps.Logger.Infof("last entry in WAL is a viewChange message")
149			return nil
150		}
151	
152		return fmt.Errorf("unrecognized record: %v", lastPersistedMessage)
153	}
154	
155	func (ps *PersistedState) recoverProposed(lastPersistedMessage *protos.ProposedRecord, v *View) error {
156		prop := lastPersistedMessage.GetPrePrepare().Proposal
157		v.inFlightProposal = &types.Proposal{
158			VerificationSequence: int64(prop.VerificationSequence),
159			Metadata:             prop.Metadata,
160			Payload:              prop.Payload,
161			Header:               prop.Header,
162		}
163		ps.storeProposal(lastPersistedMessage)
164		// Reconstruct the prepare message we shall next broadcast
165		// after the recovery.
166		prp := lastPersistedMessage.GetPrePrepare()
167		v.lastBroadcastSent = &protos.Message{
168			Content: &protos.Message_Prepare{
169				Prepare: lastPersistedMessage.GetPrepare(),
170			},
171		}
172		v.Phase = PROPOSED
173		v.Number = prp.View
174		v.ProposalSequence = prp.Seq
175		md := &protos.ViewMetadata{}
176		if err := proto.Unmarshal(prop.Metadata, md); err != nil {
177			ps.Logger.Panicf("Failed to unmarshal proposal metadata, error: %v", err)
178		}
179		v.DecisionsInView = md.DecisionsInView
180		ps.Logger.Infof("Restored proposal with sequence %d", lastPersistedMessage.GetPrePrepare().Seq)
181		return nil
182	}
183	
184	func (ps *PersistedState) recoverPrepared(lastPersistedMessage *protos.Message, v *View, entries [][]byte) error {
185		// Last entry is a commit, so we should have not pruned the previous pre-prepare
186		if len(entries) < 2 {
187			return errors.New("last message is a commit, but expected to also have a matching pre-prepare")
188		}
189		prePrepareMsg := &protos.SavedMessage{}
190		if err := proto.Unmarshal(entries[len(entries)-2], prePrepareMsg); err != nil {
191			ps.Logger.Errorf("Failed unmarshaling second last entry from WAL: %v", err)
192			return fmt.Errorf("failed unmarshaling last entry from WAL: %w", err)
193		}
194	
195		prePrepareFromWAL := prePrepareMsg.GetProposedRecord().GetPrePrepare()
196	
197		if prePrepareFromWAL == nil {
198			return fmt.Errorf("expected second last message to be a pre-prepare, but got '%v' instead", prePrepareMsg)
199		}
200	
201		if v.ProposalSequence < prePrepareFromWAL.Seq {
202			err := fmt.Errorf("last proposal sequence persisted into WAL is %d which is greater than last committed sequence is %d", prePrepareFromWAL.Seq, v.ProposalSequence)
203			ps.Logger.Errorf("Failed recovery: %s", err)
204			return err
205		}
206	
207		// Check if the WAL's last sequence has been persisted into the application layer.
208		if v.ProposalSequence > prePrepareFromWAL.Seq {
209			ps.Logger.Infof("Last proposal with sequence %d has been safely committed", v.ProposalSequence)
210			return nil
211		}
212	
213		// Else, v.ProposalSequence == prePrepareFromWAL.Seq
214	
215		prop := prePrepareFromWAL.Proposal
216		v.inFlightProposal = &types.Proposal{
217			VerificationSequence: int64(prop.VerificationSequence),
218			Metadata:             prop.Metadata,
219			Payload:              prop.Payload,
220			Header:               prop.Header,
221		}
222		ps.storeProposal(prePrepareMsg.GetProposedRecord())
223		ps.storePrepared(lastPersistedMessage)
224	
225		// Reconstruct the commit message we shall next broadcast
226		// after the recovery.
227		v.lastBroadcastSent = lastPersistedMessage
228		v.Phase = PREPARED
229		v.Number = prePrepareFromWAL.View
230		v.ProposalSequence = prePrepareFromWAL.Seq
231		md := &protos.ViewMetadata{}
232		if err := proto.Unmarshal(prop.Metadata, md); err != nil {
233			ps.Logger.Panicf("Failed to unmarshal proposal metadata, error: %v", err)
234		}
235		v.DecisionsInView = md.DecisionsInView
236	
237		// Restore signature
238		signatureInLastSentCommit := v.lastBroadcastSent.GetCommit().Signature
239		v.myProposalSig = &types.Signature{
240			ID:    signatureInLastSentCommit.Signer,
241			Msg:   signatureInLastSentCommit.Msg,
242			Value: signatureInLastSentCommit.Value,
243		}
244	
245		ps.Logger.Infof("Restored proposal with sequence %d", prePrepareFromWAL.Seq)
246		return nil
247	}
248

