163	// computeQuorum calculates the quorums size Q, given a cluster size N.
164	//
165	// The calculation satisfies the following:
166	// Given a cluster size of N nodes, which tolerates f failures according to:
167	//
168	//	f = argmax ( N >= 3f+1 )
169	//
170	// Q is the size of the quorum such that:
171	//
172	//	any two subsets q1, q2 of size Q, intersect in at least f+1 nodes.
173	//
174	// Note that this is different from N-f (the number of correct nodes), when N=3f+3. That is, we have two extra nodes
175	// above the minimum required to tolerate f failures.
176	func computeQuorum(n uint64) (q int, f int) {
177		f = (int(n) - 1) / 3
178		q = int(math.Ceil((float64(n) + float64(f) + 1) / 2.0))
179		return
180	}
