374		buff.WriteString("< NewView with ")
375		for i, svd := range nv.SignedViewData {
376			buff.WriteString(signedViewDataToString(svd))
377			if i == len(nv.SignedViewData)-1 {
378				break
379			}
380			buff.WriteString(", ")
381		}
382		buff.WriteString(">")
383		return buff.String()
